// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/products", wrapper.BrowseProducts)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/products/{id}", wrapper.GetProduct)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/skus/{id}", wrapper.GetSKU)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/categories", wrapper.GetCategoryTree)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/suppliers", wrapper.ListPublicSuppliers)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/products", wrapper.CreateProduct)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/admin/products/{id}", wrapper.DeleteProduct)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/admin/products/{id}", wrapper.UpdateProduct)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/products/{id}/variants", wrapper.AddVariant)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/products/{id}/skus", wrapper.CreateSKU)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/admin/skus/{id}", wrapper.DeleteSKU)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/admin/skus/{id}", wrapper.UpdateSKU)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/products/{id}/images", wrapper.AttachImage)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/admin/products/{id}/images/{image_id}", wrapper.DetachImage)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/categories", wrapper.CreateCategory)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/admin/categories/{id}", wrapper.DeleteCategory)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/admin/categories/{id}", wrapper.UpdateCategory)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/sysadmin/suppliers", wrapper.ListSuppliers)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/sysadmin/suppliers", wrapper.CreateSupplier)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/sysadmin/suppliers/{id}", wrapper.DeleteSupplier)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/sysadmin/suppliers/{id}", wrapper.GetSupplier)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/sysadmin/suppliers/{id}", wrapper.UpdateSupplier)
	})

	return r
}

